// il punto del filmato `a` che somiglia di piu' al punto `t` (secondi) del filmato `da`
function filmPuntoAbbinato(da, a, t) {
  const j = FILM_ABBINA; const lista = j && j.da && j.da[da] && j.da[da][a];
  if (!lista || !lista.length) return 0;
  const dur = Number((j.durata || {})[da]) || 0;
  let tt = Number(t) || 0; if (dur > 0) tt = ((tt % dur) + dur) % dur;
  return Math.max(0, Number(lista[Math.round(tt / (Number(j.passo) || 0.25)) % lista.length]) || 0);
}
function FILM_CONS(cls, tre) {
  const f = tre ? FILM_TRE : FILM_PRONTO;
  return `<span class="donnina gov-fig gov-film ${cls}" role="img" aria-label="${esc(nomeGov())}" data-film="riposo"${tre ? ' data-tre="1"' : ""}>
    <video class="cf-v" src="${f.riposo}" poster="${f.poster}" autoplay muted playsinline loop preload="auto"></video>
    <video class="cf-v giu" poster="${f.poster}" muted playsinline loop preload="none"></video>
  </span>`;
}
// i file dei filmati per quella casella: in 3D quelli ritagliati, altrimenti i soliti
function filmFile(box) { return (box && box.dataset && box.dataset.tre === "1") ? FILM_TRE : FILM_PRONTO; }
let filmTimer = null;
function filmGov(quale, soloBox) {
  const caselle = soloBox ? [soloBox] : [...document.querySelectorAll(".gov-film")];
  for (const b of caselle) filmUno(quale, b, true);
}
// Prepara il filmato `quale` nel video nascosto (gia' al punto giusto) e lo manda in dissolvenza al posto di quello in corso.
function filmUno(quale, box) {
  if (!box || !FILM_PRONTO[quale] || box.dataset.occupato === "1") return;
  if (box.dataset.film === quale) { box._prep = null; return; }
  const vs = [...box.querySelectorAll("video")];
  if (vs.length < 2) return;
  const su = vs.find(v => !v.classList.contains("giu")) || vs[0];
  const giu = vs.find(v => v !== su);
  let p = box._prep;
  if (!p || p.quale !== quale) {
    const da = box.dataset.film || "";
    const inizio = da ? filmPuntoAbbinato(da, quale, (Number(su.currentTime) || 0) + 0.3) : 0;
    p = box._prep = { quale, pronto: false, da: Date.now(), inizio };
    const segna = () => { if (box._prep === p) p.pronto = true; };
    const vaiA = () => {
      if (inizio > 0.05) { giu.addEventListener("seeked", segna, { once: true }); try { giu.currentTime = inizio; } catch (e) { segna(); } }
      else { try { if ((Number(giu.currentTime) || 0) > 0.05) giu.currentTime = 0; } catch (e) {} segna(); }
    };
    giu.loop = true;
    try { giu.playbackRate = 1; } catch (e) {}
    const file = filmFile(box)[quale];
    if (giu.getAttribute("src") === file && giu.readyState >= 1) vaiA();
    else { giu.src = file; giu.preload = "auto"; giu.addEventListener("loadedmetadata", vaiA, { once: true }); giu.load(); }
  }
  // pronto = gia' al punto giusto e con l'immagine; se il salto non risponde in 3 s si va lo stesso (mai un nero)
  const pronto = (p.pronto && giu.readyState >= 2) || (Date.now() - p.da > 3000 && giu.readyState >= 3);
  if (!pronto) {                              // ci riprova filmVigila fra 150 ms
    // 1.11.0: il filmato da preparare non si carica (errore, niente dati) entro 6 secondi: si ricomincia da capo; alla
    // terza volta si cambia direttamente quello in vista (senza dissolvenza): Sofia si muove comunque, non resta ferma
    if (giu.error || Date.now() - p.da > 6000) {
      box._prep = null; box._prepFalliti = (box._prepFalliti || 0) + 1;
      console.warn("filmato: preparazione fallita", quale, box._prepFalliti);
      if (box._prepFalliti >= 3) {
        box._prepFalliti = 0;
        try { su.src = filmFile(box)[quale]; su.loop = true; su.load(); su.play().catch(() => {}); box.dataset.film = quale; } catch (e) {}
      } else { try { giu.removeAttribute("src"); giu.load(); } catch (e) {} }
    }
    return;
  }
  box._prepFalliti = 0;
  box.dataset.occupato = "1"; box._prep = null;
  giu.play().catch(() => {});
  giu.classList.remove("giu");
  su.classList.add("giu");
  box.dataset.film = quale;
  setTimeout(() => { try { su.pause(); } catch (e) {} box.dataset.occupato = ""; }, FILM_DISSOLVENZA + 80);
}
// 1.11.0 (Michele: "quando Sofia parla ogni tanto si blocca"): un filmato che risulta "in corsa" ma e' fermo sullo stesso
// fotogramma (la decodifica si e' piantata) riceve una spinta; dopo tre spinte inutili si ricarica dal punto dov'era
function filmSpinta(v) {
  const ora = Date.now(), ct = Number(v.currentTime) || 0;
  if (v._ct !== ct) { v._ct = ct; v._ctDa = ora; v._spinte = 0; return; }
  if (!v._ctDa) { v._ctDa = ora; return; }
  if (ora - v._ctDa < 1600) return;
  v._ctDa = ora; v._spinte = (v._spinte || 0) + 1;
  console.warn("filmato fermo: spinta", v._spinte);
  try {
    if (v._spinte >= 3) {
      v._spinte = 0;
      v.addEventListener("loadedmetadata", () => { try { v.currentTime = ct; } catch (e) {} v.play().catch(() => {}); }, { once: true });
      v.load(); return;
    }
    const d = Number(v.duration) || 0; v.currentTime = d ? (ct + 0.15) % d : ct + 0.15;
  } catch (e) {}
  v.play().catch(() => {});
}
// 1.11.0: il filmato in vista e' fermo e il telefono ha buttato via i dati (succede tornando dallo sfondo): dopo 2,5 s
// si ricarica dal punto dov'era e riparte
function filmRianima(v) {
  const ora = Date.now();
  if (!v._fermoDa) { v._fermoDa = ora; return; }
  if (ora - v._fermoDa < 2500) return;
  v._fermoDa = ora;
  try { const t = Number(v.currentTime) || 0; v.addEventListener("loadedmetadata", () => { try { v.currentTime = t; } catch (e) {} v.play().catch(() => {}); }, { once: true }); v.load(); } catch (e) {}
}
function filmVigila() {
  if (filmTimer) return;
  filmTimer = setInterval(() => {
    if (document.hidden) return;
    const forzato = document.body.dataset.cons || "";
    let suono = false; try { suono = VOCE.staParlando(); } catch (e) {}
    for (const b of document.querySelectorAll(".gov-film")) {
      // 1.0: una Sofia nascosta (quella che "esce" quando parla, a riposo) non consuma batteria
      if (b.closest("[hidden]")) { for (const v of b.querySelectorAll("video")) if (!v.paused) { try { v.pause(); } catch (e) {} } continue; }
      const vuole = forzato === "parla" || b.classList.contains("parla") || !!b.closest(".sta-parlando") || (voceInCorso && !!b.closest("#sofiaHero, #sofiaFuori, .sofia-vista"));
      const parla = vuole && (suono || voceInCorso);
      const ascolta = !parla && forzato === "ascolto";
      const pensa = !parla && !ascolta && forzato === "pensa";
      const quale = FILM_GRUPPI[parla ? "parla" : ascolta ? "ascolta" : pensa ? "pensa" : "riposo"];
      const su = [...b.querySelectorAll("video")].find(v => !v.classList.contains("giu"));
      // il filmato in vista gira da solo (loop): se per qualche motivo si e' fermato, riparte
      if (su && !su.loop) su.loop = true;
      if (su && su.paused && !b.dataset.occupato && su.readyState >= 2) su.play().catch(() => {});
      else if (su && su.paused && !b.dataset.occupato) filmRianima(su);   // 1.11.0: fermo e senza immagine (dopo lo sfondo)
      if (su && !su.paused) su._fermoDa = 0;
      if (su && !su.paused && !b.dataset.occupato && b.offsetWidth > 0) filmSpinta(su);   // 1.11.0
      if ((b.dataset.film || "") !== quale) filmUno(quale, b);
    }
  }, 150);
}
filmVigila();
let micCasa = null, micAttivo = false, micAnnullato = false;
