    const html = tasti.map(t => `<button type="button" class="${t.k === "si" ? "vb-si" : t.k === "no" ? "vb-no" : "vb-altro"}" data-casa-tasto="${esc(String(n - 1))}|${esc(String(t.k))}">${esc(t.testo)}</button>`).join("");
