async function casaAllegato(file) {
  if (!file) return;
  const nome = String(file.name || "").toLowerCase(), tipo = String(file.type || "");
  if (/\.(xlsx|xlsm|xls|ods)$/.test(nome) || /sheet|excel/.test(tipo)) { leggiFileExcel(file); return; }
  if (!/^image\//.test(tipo) && !/\.(jpe?g|png|webp)$/.test(nome)) { toast("Mandami una foto o il foglio Excel."); return; }
  if (!iaAccesa()) { toast(`Per leggere le foto ${nomeGov()} deve essere intelligente: serve la chiave di Gemini (Altro → Governante intelligente).`); return; }
  let img; try { img = await fotoPiccola(file); } catch (e) { toast("Non riesco ad aprire questa foto."); return; }
  const conv = [...conversazione(), { chi: "io", testo: "📷 Ti mando una foto", ora: S.db.adesso() }];
  salvaConversazione(conv); govScrive = true; disegna();
  let msg = null;
  try {
    msg = await rispostaIA(`Ti mando una FOTO. Se è una COSA ROTTA, SPORCA O DA SISTEMARE (un rubinetto, una lampadina, una macchia, un vetro…), metti l'azione "manutenzione" con "modo":"apri", in "cosa" quello che si vede (corto) e la camera se si capisce; se la camera non si capisce, aprila senza camera e chiedimi in quale camera è. Se invece è IL PROSPETTO (il foglio di papà: le camere e i giorni), leggilo camera per camera e mettimi l'azione "prospetto" con una riga per ogni ospite che vedi, nel formato "Camera: Nome, N persone, dal GG mese al GG mese" (il giorno dopo "al" è quello di partenza). NON mettere righe "libera". Se un nome o una data non si legge bene, metti il punto di domanda dopo il nome. Nella risposta dimmi in una frase che giorni copre la foto e quanti ospiti hai letto.`, conv, img);
  } catch (e) { console.warn("foto", e); msg = { chi: "gov", testo: "Non sono riuscita a leggere la foto: " + String(e.message || e), ora: S.db.adesso() }; }
  govScrive = false;
  salvaConversazione([...conversazione(), msg]);
  if (voceAccesa() && msg && msg.testo) parlaConVoce(String(msg.testo).split("\n")[0], { inChat: true });
}
// la foto rimpicciolita (lato lungo 1800 punti, JPEG): basta per leggere e non pesa
async function fotoPiccola(file) {
  const url = URL.createObjectURL(file);
  try {
    const im = await new Promise((ok, ko) => { const i = new Image(); i.onload = () => ok(i); i.onerror = ko; i.src = url; });
    const k = Math.min(1, 1800 / Math.max(im.naturalWidth || 1, im.naturalHeight || 1));
    const c = document.createElement("canvas"); c.width = Math.max(1, Math.round(im.naturalWidth * k)); c.height = Math.max(1, Math.round(im.naturalHeight * k));
    c.getContext("2d").drawImage(im, 0, 0, c.width, c.height);
    return { mime: "image/jpeg", dati: c.toDataURL("image/jpeg", 0.85).split(",")[1] };
  } finally { URL.revokeObjectURL(url); }
}
// "sì" / "no" detti a voce (o scritti) quando lei ha appena proposto qualcosa: valgono come il tocco sul tasto
async function casaRispostaVoce(t) {
  const conv = conversazione(); const i = conv.length - 1; const m = conv[i];
  if (!m || m.chi !== "gov" || !Array.isArray(m.tasti) || !m.tasti.length || !m.azione) return false;
  const x = String(t || "").trim().toLowerCase();
  const fine = "(?![a-zà-ÿ])";   // non \b: dopo la "ì" di "sì" il \b non scatta
  // 1.11.0: «sì, però aggiungi anche Alba» o «no, mettilo domani» non sono un sì o un no e basta: c'e' una modifica, e
  // allora la frase va all'IA (prima la proposta vecchia partiva lo stesso e la modifica si perdeva)
  const dopo = x.replace(/[^\p{L}\p{N}' ]+/gu, " ").split(/\s+/).filter(Boolean).slice(1);
  const modifica = dopo.some(w => ["ma", "però", "pero", "invece", "anche", "aggiungi", "cambia", "togli", "metti", "mettilo", "mettila", "sposta", "tranne", "solo", "aspetta"].includes(w));
  if (!modifica && new RegExp("^(s[iì]|va bene|vai|fallo|falla|ok|okay|certo|confermo|conferma|d'accordo|perfetto|esatto|giusto)" + fine).test(x) && x.length < 40) { await rispondiParole(i, "si"); return true; }
  if (!modifica && new RegExp("^(no|lascia|niente|non farlo|non fare|annulla|aspetta)" + fine).test(x) && x.length < 40) { await rispondiParole(i, "no"); return true; }
  if (m.azione.tipo === "gruppo" && /^(una per una|una alla volta|una a una|una ad una)/.test(x)) { await rispondiParole(i, "una"); return true; }
  return false;
}
