  const std = Number(p.minuti) || 0, l = L.listinoCompleto(S.listino), aMinuto = l.pagaCol === "vero" && std;
  const tariffa = L.tariffaDi(S.listino, camera(p.camera)), tetto = std ? Math.round(std * (1 + (Number(l.tolleranzaCrono) || 0) / 100)) : 0;
