  const stato = occ.length || lib.length ? ` ${occ.length ? "Occupate: " + occ.join("; ") + "." : ""}${lib.length ? ` Libere: ${lib.length > 6 ? lib.length + " camere" : lib.join(", ")}.` : ""}` : "";
