      const patch = { dettagli: dett, dettagliDa: (S.utente && S.utente.nome) || "papà", dettagliOra: S.db.adesso() };
      Object.assign(p, patch); ops.push({ tipo: "aggiorna", coll: "pulizie", id: p.id, dati: patch });
