  if (offCD === 0xffffffff || offCD + dimCD > tot) throw new Error("zip troppo grande o rovinato");
  const cd = await pezzo(offCD, offCD + dimCD), dv = new DataView(cd.buffer), dec = new TextDecoder();
  const voci = [];
