    document.querySelectorAll("[data-ins-copia]").forEach(b => b.onclick = () => { const d = statoDettatura(); d.scelte = {}; d.comportamenti = {}; d.fonte = null; d.rif = ""; apriFoglio({ tipo: "dettatura", copia: true }); });
